def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Locate 3x3 marker rings around a central 2.
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
                if (rr, cc) != (r, c)
            ):
                centers.append((r, c))

    if not centers:
        return out

    # The 2-lines run along the direction with the most densely populated lines.
    row_lines = sum(sum(v == 2 for v in row) >= max(4, w // 2) for row in grid)
    col_lines = sum(
        sum(grid[r][c] == 2 for r in range(h)) >= max(4, h // 2)
        for c in range(w)
    )
    vertical_walls = col_lines >= row_lines

    for sr, sc in centers:
        # Extend the beam perpendicular to the 2-lines.
        if vertical_walls:
            for c in range(w):
                if out[sr][c] == 0:
                    out[sr][c] = 1
            crossings = [(sr, c) for c in range(w) if grid[sr][c] == 2 and c != sc]
        else:
            for r in range(h):
                if out[r][sc] == 0:
                    out[r][sc] = 1
            crossings = [(r, sc) for r in range(h) if grid[r][sc] == 2 and r != sr]

        # Mark each crossed wall with a 1-colored ring, keeping its center 2.
        for r, c in crossings:
            for rr in range(max(0, r - 1), min(h, r + 2)):
                for cc in range(max(0, c - 1), min(w, c + 2)):
                    if (rr, cc) != (r, c) and out[rr][cc] != 3:
                        out[rr][cc] = 1

    return out
